from django.db import migrations


def migrate_farmer_membership_data(apps, schema_editor):
    Farmer = apps.get_model('farmers', 'Farmer')
    FarmersOrganizationMember = apps.get_model('associations', 'FarmersOrganizationMember')

    for farmer in Farmer.objects.filter(farmers_organization_id__isnull=False):
        FarmersOrganizationMember.objects.get_or_create(
            organization_id=farmer.farmers_organization_id,
            farmer_id=farmer.id,
            defaults={
                'position': 'Member',
                'date_joined': farmer.date_registered.date() if farmer.date_registered else None,
                'is_active': farmer.is_org_membership_active,
                'deactivation_reason': farmer.org_membership_deactivation_reason or '',
                'is_main': True,
            },
        )


def resolve_fisherfolk_is_main(apps, schema_editor):
    Fisherfolk = apps.get_model('fisheries', 'Fisherfolk')
    FisherfolkOrganizationMember = apps.get_model('associations', 'FisherfolkOrganizationMember')

    fisherfolk_ids = (
        FisherfolkOrganizationMember.objects
        .filter(is_active=True)
        .values_list('fisherfolk_id', flat=True)
        .distinct()
    )
    for fid in fisherfolk_ids:
        active = list(
            FisherfolkOrganizationMember.objects
            .filter(fisherfolk_id=fid, is_active=True)
            .order_by('date_joined', 'id')
        )
        if not active:
            continue
        main = active[0]
        if len(active) > 1:
            try:
                fisherfolk = Fisherfolk.objects.get(pk=fid)
                matches = [m for m in active if m.organization.barangay == fisherfolk.barangay]
                if len(matches) == 1:
                    main = matches[0]
            except Fisherfolk.DoesNotExist:
                pass
        main.is_main = True
        main.save(update_fields=['is_main'])


